//! Help ▸ About AnyFont ▸ Legal Notices... (UI-SPEC §7.2.3): AnyFont's licence and the third-party notices
//! (`THIRD-PARTY-NOTICES.txt`, regenerated by `build.bat`), in a white, scrolling, read-only pane with
//! Print (left) and OK (right, default). Declared by `about.rs` (`crate::about::legal`).

use crate::help::dlg;
use egui::{pos2, vec2, Color32, Rect, Stroke, StrokeKind};

/// AnyFont's own licence (the repository's `LICENSE`).
pub const LICENSE: &str = include_str!("../../../LICENSE");
/// The open-source components and their licences.
pub const THIRD_PARTY: &str = include_str!("../../../THIRD-PARTY-NOTICES.txt");

/// The whole text of the pane (and of Print).
pub fn text() -> String {
    format!("{}\n\n{}\n", LICENSE.trim_end(), THIRD_PARTY.trim_end()).replace("\r\n", "\n")
}

/// The text as the pane shows it: the files are wrapped at about 75 columns, so a long line followed by
/// more prose is joined to it and the pane wraps the paragraph to its own width. Indented lines (the
/// licence counts, each component's licence and address) and short lines stay as they are.
pub fn reflow(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut prev_long = false;
    for (i, line) in text.split('\n').enumerate() {
        let joins = prev_long && !line.trim().is_empty() && !line.starts_with(char::is_whitespace);
        if i > 0 {
            out.push(if joins { ' ' } else { '\n' });
        }
        out.push_str(if joins { line.trim_start() } else { line });
        prev_long = line.trim_end().chars().count() >= 60;
    }
    out
}

/// Print: the text goes to a file in the temporary folder, which Windows prints with the program
/// registered for text files (the "print" verb, Notepad by default) on the default printer.
pub fn print() -> bool {
    let path = std::env::temp_dir().join("AnyFont Legal Notices.txt");
    if std::fs::write(&path, text().replace('\n', "\r\n")).is_err() {
        return false;
    }
    #[cfg(windows)]
    {
        use windows::core::HSTRING;
        use windows::Win32::UI::Shell::ShellExecuteW;
        use windows::Win32::UI::WindowsAndMessaging::SW_HIDE;
        let r = unsafe { ShellExecuteW(None, &HSTRING::from("print"), &HSTRING::from(path.as_os_str()), None, None, SW_HIDE) };
        r.0 as isize > 32
    }
    #[cfg(not(windows))]
    {
        false
    }
}

/// Shows the dialog; true when it was closed.
pub fn ui(ctx: &egui::Context, text: &str) -> bool {
    let mut close = false;
    let ((), dismissed) = dlg::window(ctx, "legal_notices", "Legal Notices", vec2(514.0, 739.0), |ui| {
        let (top, bar) = dlg::split_bottom(ui, dlg::BUTTON_H);
        let pane = Rect::from_min_max(pos2(top.left(), top.top() + 4.0), top.max);
        // white in every theme, as captured
        ui.painter().rect_filled(pane, 0.0, Color32::WHITE);
        ui.painter().rect_stroke(pane, 0.0, Stroke::new(1.0, Color32::from_gray(0x80)), StrokeKind::Inside);
        dlg::at(ui, pane.shrink2(vec2(8.0, 6.0)), |ui| {
            egui::ScrollArea::vertical().auto_shrink([false, false]).show(ui, |ui| {
                // a LayoutJob: licence texts are never translated
                let job = egui::text::LayoutJob::simple(reflow(text), egui::FontId::proportional(13.0), Color32::from_gray(0x10), ui.available_width());
                ui.add(egui::Label::new(job).selectable(true));
            });
        });
        dlg::at_left(ui, bar, |ui| {
            if dlg::button(ui, "Print", true) && !print() {
                log::warn!("could not print the legal notices");
            }
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                if dlg::default_button(ui, "OK", true) || dlg::enter_pressed(ui) {
                    close = true;
                }
            });
        });
    });
    close || dismissed
}

#[cfg(test)]
mod tests {
    #[test]
    fn notices_name_anyfont_and_the_components() {
        let t = super::text();
        assert!(t.contains("AnyFont"));
        assert!(t.contains("open-source components"));
        assert!(!t.contains('\r'));
    }

    #[test]
    fn reflow_joins_wrapped_prose_only() {
        let long = "x".repeat(70);
        let t = format!("{long}\nmore words\n\nshort\nnext\n{long}\n    License: MIT\n");
        assert_eq!(super::reflow(&t), format!("{long} more words\n\nshort\nnext\n{long}\n    License: MIT\n"));
    }
}
